mapper.select:
SELECT * FROM TBL_ASSESS_PLAN p WHERE 1=1

	AND ASSESSID LIKE
	concat(concat('%',#{queryParam.assessid}),'%')


	AND ASSESSNAME LIKE
	concat(concat('%',#{queryParam.assessname}),'%')


	AND ( CREATESTAFFID=#{queryParam.createstaffid} OR LEADERID
	=#{queryParam.createstaffid} )


	AND STATUS=#{queryParam.status}


	and startdate >=#{queryParam.startdate}


	and startdate <=#{queryParam.startdates}


	and endDate >=#{queryParam.enddate}


	and endDate <=#{queryParam.enddates}



	${sql}

ORDER BY ASSID DESC
